// The typed API layer (DSN-SDK-001 layer 4, DSN-SDK-012): what code generated by
// `forge types` (DSN-FRG-102) builds on — items typed by class, so that a polymorphic
// result is a discriminated union narrowed on `class`, and query builders that compile to
// DAT-Query (STD-EXPR-010).

import type { Client, Item, Selectors } from "./client.js";
import { Decimal } from "./decimal.js";
import { errorOf } from "./errors.js";

/** An item of class `C` with the body `B`; a union of them narrows on `class`. */
export type Typed<C extends string, B> = Item<B> & { readonly class: C };

/** The criteria query object (STD-EXPR-010). */
export interface DatQuery {
  from: string;
  only?: boolean;
  where?: string;
  states?: string[];
  select?: string[];
  order_by?: { path: string; dir: "asc" | "desc" }[];
  limit?: number;
  cursor?: string;
}

/** A comparison of the L1 expression language. */
export type Comparison = "==" | "!=" | "<" | "<=" | ">" | ">=";

/** A value a builder can compare with. */
export type Literal = string | number | boolean | null | Decimal;

/** The L1 literal of a value: strings quoted with the escapes of STD-EXPR-001, integers,
 * exact decimals; floating-point numbers are refused. */
export function literal(v: Literal): string {
  if (v === null) return "null";
  if (typeof v === "boolean") return String(v);
  if (v instanceof Decimal) return v.toString();
  if (typeof v === "number") {
    if (!Number.isSafeInteger(v)) {
      throw errorOf("LOGIC.FLOAT_TO_DECIMAL", "compare decimals as Decimal values", { value: v });
    }
    return String(v);
  }
  let out = '"';
  for (const ch of v) {
    const c = ch.codePointAt(0) ?? 0;
    if (ch === '"' || ch === "\\") out += `\\${ch}`;
    else if (ch === "\n") out += "\\n";
    else if (ch === "\r") out += "\\r";
    else if (ch === "\t") out += "\\t";
    else if (c < 0x20 || c === 0x2028 || c === 0x2029) out += `\\u${c.toString(16).padStart(4, "0")}`;
    else out += ch;
  }
  return `${out}"`;
}

/** A query of one class (and its subclasses unless `only`), its results typed `T`, its
 * filters and ordering over the fields of `B`. Immutable: every method returns a new
 * builder. */
export class Query<T, B = Record<string, unknown>> {
  constructor(readonly spec: Readonly<DatQuery>) {}

  #with(more: Partial<DatQuery>): Query<T, B> {
    return new Query<T, B>({ ...this.spec, ...more });
  }

  /** Exclude subclasses. */
  only(): Query<T, B> {
    return this.#with({ only: true });
  }

  /** And an L1 boolean expression over `this`. */
  where(expression: string): Query<T, B> {
    const w = this.spec.where ? `(${this.spec.where}) and (${expression})` : expression;
    return this.#with({ where: w });
  }

  /** And a comparison of a field with a value (`null` compares with `is null`). */
  filter<K extends keyof B & string>(field: K, op: Comparison, value: Literal): Query<T, B> {
    if (value === null && (op === "==" || op === "!=")) {
      return this.where(`this.${field} is ${op === "==" ? "" : "not "}null`);
    }
    return this.where(`this.${field} ${op} ${literal(value)}`);
  }

  /** Lifecycle states. */
  inStates(...states: string[]): Query<T, B> {
    return this.#with({ states });
  }

  /** The fields to return. */
  select(...fields: (keyof B & string)[]): Query<T, B> {
    return this.#with({ select: fields.map((f) => `this.${f}`) });
  }

  /** Then order by a field. */
  orderBy<K extends keyof B & string>(field: K, dir: "asc" | "desc" = "asc"): Query<T, B> {
    return this.#with({ order_by: [...(this.spec.order_by ?? []), { path: `this.${field}`, dir }] });
  }

  /** The page size. */
  limit(n: number): Query<T, B> {
    return this.#with({ limit: n });
  }

  /** The DAT-Query object. */
  toQuery(): DatQuery {
    return JSON.parse(JSON.stringify(this.spec)) as DatQuery;
  }

  /** Every result, following the cursors within one snapshot. */
  async *run(client: Client, sel?: Selectors & { pageSize?: number }): AsyncGenerator<T> {
    const q = this.toQuery() as unknown as Record<string, unknown>;
    for await (const item of client.query(q, { pageSize: this.spec.limit ?? 100, ...sel })) yield item as T;
  }

  /** Every result in an array. */
  async all(client: Client, sel?: Selectors): Promise<T[]> {
    const out: T[] = [];
    for await (const x of this.run(client, sel)) out.push(x);
    return out;
  }
}

/** Read one object of a class by slug, typed. */
export function getTyped<T>(client: Client, cls: string, slug: string, sel?: Selectors): Promise<T> {
  return client.get(`ubos://${client.options.vae}/${cls}/${slug}`, sel) as Promise<T>;
}
